CREATE FUNCTION public.people_owner(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_access_control WHERE tenant_id=t AND user_id=u AND position='owner' AND status='active') AND public.user_has_tenant(u,t) $$;
CREATE FUNCTION public.people_access(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT u IS NOT NULL AND (public.is_super_admin(u) OR public.user_has_tenant(u,t)) AND NOT EXISTS(SELECT 1 FROM public.user_access_control WHERE tenant_id=t AND user_id=u AND status='disabled') AND (public.has_role(u,'admin') OR public.has_role(u,'manager') OR public.people_owner(t,u)) $$;
CREATE TABLE public.people_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,venue_id uuid REFERENCES public.venues(id),values jsonb NOT NULL DEFAULT '{}'::jsonb,updated_by uuid,updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX people_settings_scope ON public.people_settings(tenant_id,COALESCE(venue_id,'00000000-0000-0000-0000-000000000000'::uuid));
GRANT SELECT ON public.people_settings TO authenticated;GRANT ALL ON public.people_settings TO service_role;ALTER TABLE public.people_settings ENABLE ROW LEVEL SECURITY;CREATE POLICY settings_read ON public.people_settings FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) OR public.is_super_admin(auth.uid()));
CREATE TABLE public.hr_employment_terms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,employee_id uuid NOT NULL REFERENCES public.hr_employees(id) ON DELETE CASCADE,effective_date date NOT NULL,values jsonb NOT NULL,created_by uuid NOT NULL,approved_by uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_employment_terms TO authenticated;GRANT ALL ON public.hr_employment_terms TO service_role;ALTER TABLE public.hr_employment_terms ENABLE ROW LEVEL SECURITY;CREATE POLICY terms_read ON public.hr_employment_terms FOR SELECT TO authenticated USING(public.people_access(tenant_id,auth.uid()));
CREATE TABLE public.hr_people_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,employee_id uuid REFERENCES public.hr_employees(id) ON DELETE CASCADE,effective_date date NOT NULL,values jsonb NOT NULL,change_type text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),approval_mode text NOT NULL,created_by uuid NOT NULL,approved_by uuid,approved_at timestamptz,document_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_people_changes TO authenticated;GRANT ALL ON public.hr_people_changes TO service_role;ALTER TABLE public.hr_people_changes ENABLE ROW LEVEL SECURITY;CREATE POLICY changes_read ON public.hr_people_changes FOR SELECT TO authenticated USING(public.people_access(tenant_id,auth.uid()));
CREATE TABLE public.hr_person_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,employee_id uuid NOT NULL REFERENCES public.hr_employees(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('contract','id','permit','sick_note','letter')),file_name text NOT NULL,storage_path text NOT NULL UNIQUE,mime_type text NOT NULL,expiry_date date,version integer NOT NULL,previous_id uuid REFERENCES public.hr_person_documents(id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_person_documents TO authenticated;GRANT ALL ON public.hr_person_documents TO service_role;ALTER TABLE public.hr_person_documents ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.people_documents_access(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.people_access(t,u) AND (public.people_owner(t,u) OR (public.has_role(u,'manager') AND EXISTS(SELECT 1 FROM public.user_page_permissions WHERE user_id=u AND tenant_id=t AND page_key='people' AND can_access AND NOT ('people.view_documents'=ANY(COALESCE(hidden_actions,ARRAY[]::text[])))))) $$;
CREATE POLICY documents_read ON public.hr_person_documents FOR SELECT TO authenticated USING(public.people_documents_access(tenant_id,auth.uid()));
ALTER TABLE public.hr_employee_history ADD COLUMN IF NOT EXISTS approved_by uuid,ADD COLUMN IF NOT EXISTS document_id uuid REFERENCES public.hr_person_documents(id),ADD COLUMN IF NOT EXISTS change_id uuid REFERENCES public.hr_people_changes(id);
CREATE FUNCTION public.people_effective_settings(t uuid,v uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT '{"rota":true,"clock_in":"off","pay_hours":"rota","leave_requests":true,"sick_notes":true,"staff_app":false,"payslips":false,"managers_change_pay":true,"reliability":true,"approvals":"owner_run"}'::jsonb || COALESCE((SELECT values FROM public.people_settings WHERE tenant_id=t AND venue_id IS NULL),'{}'::jsonb) || COALESCE((SELECT values FROM public.people_settings WHERE tenant_id=t AND venue_id=v),'{}'::jsonb) $$;
CREATE FUNCTION public.save_people_settings(t uuid,v uuid,p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; BEGIN
IF NOT public.people_access(t,auth.uid()) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin required';END IF;
IF v IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.venues WHERE tenant_id=t AND id=v AND is_active) THEN RAISE EXCEPTION 'Active venue required';END IF;
IF jsonb_typeof(p)<>'object' THEN RAISE EXCEPTION 'Invalid settings';END IF;
FOR k IN SELECT jsonb_object_keys(p) LOOP
IF k IN ('rota','leave_requests','sick_notes','staff_app','payslips','managers_change_pay','reliability') THEN IF jsonb_typeof(p->k)<>'boolean' THEN RAISE EXCEPTION 'Invalid toggle';END IF;
ELSIF k='clock_in' THEN IF p->>k NOT IN ('off','phone','venue_phone') THEN RAISE EXCEPTION 'Invalid clock-in';END IF;
ELSIF k='pay_hours' THEN IF p->>k NOT IN ('rota','clock_ins','typed_monthly') THEN RAISE EXCEPTION 'Invalid hours';END IF;
ELSIF k='approvals' THEN IF p->>k NOT IN ('owner_run','managed','strict') THEN RAISE EXCEPTION 'Invalid approvals';END IF;
ELSE RAISE EXCEPTION 'Unknown setting';END IF;END LOOP;
INSERT INTO public.people_settings(tenant_id,venue_id,values,updated_by) VALUES(t,v,p,auth.uid()) ON CONFLICT(tenant_id,COALESCE(venue_id,'00000000-0000-0000-0000-000000000000'::uuid)) DO UPDATE SET values=EXCLUDED.values,updated_by=auth.uid(),updated_at=now();END $$;
REVOKE ALL ON FUNCTION public.save_people_settings(uuid,uuid,jsonb),public.people_owner(uuid,uuid),public.people_access(uuid,uuid),public.people_documents_access(uuid,uuid),public.people_effective_settings(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_people_settings(uuid,uuid,jsonb),public.people_owner(uuid,uuid),public.people_access(uuid,uuid),public.people_documents_access(uuid,uuid),public.people_effective_settings(uuid,uuid) TO authenticated,service_role;